import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

function ProviderDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showServiceModal, setShowServiceModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [showDocumentModal, setShowDocumentModal] = useState(false);
  const [showBankModal, setShowBankModal] = useState(false);
  const [showHoursModal, setShowHoursModal] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isOnline, setIsOnline] = useState(true);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [unreadCount, setUnreadCount] = useState(3);
  const [filterStatus, setFilterStatus] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Business profile state
  const [businessProfile, setBusinessProfile] = useState({
    businessName: user?.businessName || 'QuickFix Auto Care',
    ownerName: `${user?.firstName || 'John'} ${user?.lastName || 'Doe'}`,
    email: user?.email || 'owner@quickfix.com',
    phone: user?.phone || '+254712345678',
    address: user?.businessAddress || '123 Garage Street, Nairobi',
    taxId: user?.businessLicense || 'TAX123456',
    serviceRadius: '20',
    operatingHours: { open: '08:00', close: '18:00', days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] },
    logo: user?.profilePicture || 'https://ui-avatars.com/api/?background=10b981&color=fff&name=QF',
    website: 'www.quickfixautocare.com',
    socialLinks: { facebook: 'quickfixauto', instagram: 'quickfix_auto', twitter: '@quickfix' }
  });

  // Bank account state
  const [bankAccount, setBankAccount] = useState({
    accountName: '',
    accountNumber: '',
    bankName: '',
    routingNumber: ''
  });

  // Documents state
  const [documents, setDocuments] = useState([
    { name: 'Business License', uploaded: true, url: '' },
    { name: 'Insurance Certificate', uploaded: false, url: '' },
    { name: 'Tax ID Document', uploaded: false, url: '' }
  ]);

  // Settings state
  const [settings, setSettings] = useState({
    autoConfirm: false,
    priceAlerts: true,
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    calendarSync: false,
    invoiceTemplate: 'default'
  });

  const [serviceForm, setServiceForm] = useState({
    name: '', description: '', category: 'oil-change', price: '', duration: '30',
    discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: ''
  });

  // Sample notifications
  const notifications = [
    { id: 1, type: 'new_booking', title: 'New Booking!', message: 'John Doe booked Oil Change', time: '5 min ago', read: false, icon: '📅' },
    { id: 2, type: 'payment', title: 'Payment Received', message: '$49.99 received for Oil Change', time: '1 hour ago', read: false, icon: '💰' },
    { id: 3, type: 'review', title: 'New Review', message: 'Sarah left a 5-star review', time: '2 hours ago', read: false, icon: '⭐' }
  ];

  const categories = [
    { id: 'oil-change', name: 'Oil Change', icon: '🛢️' },
    { id: 'brake-repair', name: 'Brake Repair', icon: '🛑' },
    { id: 'tire-service', name: 'Tire Service', icon: '🛞' },
    { id: 'engine-repair', name: 'Engine Repair', icon: '🔧' },
    { id: 'ac-repair', name: 'AC Repair', icon: '❄️' },
    { id: 'transmission', name: 'Transmission', icon: '⚙️' },
    { id: 'detailing', name: 'Detailing', icon: '🧼' },
    { id: 'maintenance', name: 'Maintenance', icon: '📋' },
    { id: 'electrical', name: 'Electrical', icon: '⚡' },
    { id: 'body-repair', name: 'Body Repair', icon: '🚘' }
  ];

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const servicesRes = await fetch('http://localhost:5000/api/services/provider/my-services', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const servicesData = await servicesRes.json();
      if (servicesData.success) setServices(servicesData.services);

      const bookingsRes = await fetch('http://localhost:5000/api/services/provider/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const bookingsData = await bookingsRes.json();
      if (bookingsData.success) setBookings(bookingsData.bookings);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const handleServiceSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...serviceForm,
        price: parseFloat(serviceForm.price),
        duration: parseInt(serviceForm.duration),
        discountedPrice: serviceForm.discountedPrice ? parseFloat(serviceForm.discountedPrice) : undefined,
        tags: serviceForm.tags.split(',').map(t => t.trim()),
        requirements: serviceForm.requirements.split(',').map(r => r.trim()),
        inclusions: serviceForm.inclusions.split(',').map(i => i.trim())
      };

      let url = 'http://localhost:5000/api/services';
      let method = 'POST';

      if (editingService) {
        url = `http://localhost:5000/api/services/${editingService._id}`;
        method = 'PUT';
      }

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        toast.success(editingService ? 'Service updated!' : 'Service added!');
        setShowServiceModal(false);
        setEditingService(null);
        setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' });
        fetchData();
      }
    } catch (error) {
      toast.error('Failed to save service');
    }
  };

  const handleToggleStatus = async (serviceId, currentStatus) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/${serviceId}/toggle-status`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${data.service.isActive ? 'activated' : 'deactivated'}`);
        fetchData();
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const handleDeleteService = async (serviceId) => {
    if (window.confirm('Are you sure? This action cannot be undone.')) {
      try {
        const res = await fetch(`http://localhost:5000/api/services/${serviceId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Service deleted!');
          fetchData();
        }
      } catch (error) {
        toast.error('Failed to delete service');
      }
    }
  };

  const updateBookingStatus = async (bookingId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/provider/bookings/${bookingId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Booking ${status}!`);
        fetchData();
        if (status === 'confirmed') {
          setUnreadCount(prev => Math.max(0, prev - 1));
        }
      }
    } catch (error) {
      toast.error('Failed to update booking');
    }
  };

  const editService = (service) => {
    setEditingService(service);
    setServiceForm({
      name: service.name,
      description: service.description,
      category: service.category,
      price: service.price,
      duration: service.duration,
      discountedPrice: service.discountedPrice || '',
      warranty: service.warranty || '',
      tags: (service.tags || []).join(', '),
      requirements: (service.requirements || []).join(', '),
      inclusions: (service.inclusions || []).join(', ')
    });
    setShowServiceModal(true);
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    const labels = {
      pending: '⏳ Pending',
      confirmed: '✓ Confirmed',
      'in-progress': '🔧 In Progress',
      completed: '✅ Completed',
      cancelled: '❌ Cancelled'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const markNotificationRead = (id) => {
    setUnreadCount(prev => Math.max(0, prev - 1));
  };

  const markAllRead = () => {
    setUnreadCount(0);
    toast.success('All notifications marked as read');
  };

  // Filter bookings based on status and search
  const filteredBookings = bookings.filter(booking => {
    const matchesStatus = filterStatus === 'all' || booking.status === filterStatus;
    const matchesSearch = searchTerm === '' || 
      booking.serviceName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      booking.customerId?.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      booking.customerId?.lastName?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  const completedBookings = bookings.filter(b => b.status === 'completed');
  const totalRevenue = completedBookings.reduce((sum, b) => sum + (b.totalAmount || 0), 0);
  const pendingBookings = bookings.filter(b => b.status === 'pending');
  const platformCommission = totalRevenue * 0.15;
  const growthRate = bookings.length > 0 ? ((completedBookings.length / bookings.length) * 100).toFixed(0) : 0;

  // Service performance metrics
  const serviceMetrics = services.map(service => ({
    ...service,
    bookings: bookings.filter(b => b.serviceId === service._id).length,
    revenue: bookings.filter(b => b.serviceId === service._id && b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0)
  })).sort((a, b) => b.revenue - a.revenue);

  const topService = serviceMetrics[0];

  // Peak hours analytics
  const peakHours = [9, 10, 11, 14, 15, 16].map(hour => ({
    hour: `${hour}:00`,
    bookings: Math.floor(Math.random() * 10) + 1
  }));

