          <div>
            <h1 style={styles.logoText}>{businessProfile.businessName}</h1>
            <div style={styles.headerSubtitle}>
              {user?.email} · ⭐ 4.8 · 📍 {businessProfile.address?.split(',')[0] || 'Nairobi'}
            </div>
          </div>
        </div>

        <div style={styles.headerRight}>
          {/* Online/Offline Toggle */}
          <button style={{ ...styles.onlineToggle, backgroundColor: isOnline ? '#10b981' : '#ef4444' }} onClick={() => setIsOnline(!isOnline)}>
            <span style={styles.onlineDot}></span>
            {isOnline ? 'Online' : 'Offline'}
          </button>

          {/* Notification Bell */}
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>
            🔔
            {unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}
          </div>

          {/* Settings Menu */}
          <div style={styles.userInfo}>
            <img src={businessProfile.logo} alt="logo" style={styles.avatar} />
            <button onClick={onLogout} style={styles.logoutButton}>🚪</button>
