            <button style={styles.markAllRead} onClick={markAllRead}>Mark all read</button>
          </div>
          {notifications.map(notif => (
            <div key={notif.id} style={{ ...styles.notificationItem, opacity: notif.read ? 0.6 : 1 }} onClick={() => markNotificationRead(notif.id)}>
