        <div style={styles.statCard}><h3>🛠️ Active</h3><p style={styles.statNumber}>{services.filter(s => s.isActive).length}</p></div>
        <div style={styles.statCard}><h3>📅 Pending</h3><p style={styles.statNumber}>{pendingBookings.length}</p></div>
        <div style={styles.statCard}><h3>💰 Revenue</h3><p style={styles.statNumber}>${totalRevenue.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>⭐ Rating</h3><p style={styles.statNumber}>4.8</p></div>
        <div style={styles.statCard}><h3>✅ Completed</h3><p style={styles.statNumber}>{completedBookings.length}</p></div>
        <div style={styles.statCard}><h3>📈 Growth</h3><p style={styles.statNumber}>+{growthRate}%</p></div>
      </div>

      {/* Quick Actions Bar */}
      <div style={styles.quickActions}>
        <button style={styles.quickActionBtn} onClick={() => { setEditingService(null); setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' }); setShowServiceModal(true); }}>➕ Add Service</button>
        <button style={styles.quickActionBtn} onClick={() => setActiveTab('bookings')}>📅 View Bookings</button>
