            {/* Bookings Tab */}
            {activeTab === 'bookings' && (
              <div>
                <h2>📅 All Bookings ({filteredBookings.length})</h2>
                <div style={styles.bookingFilters}>
                  <select style={styles.filterSelect} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
                    <option value="all">All Status</option>
                    <option value="pending">Pending</option>
                    <option value="confirmed">Confirmed</option>
                    <option value="in-progress">In Progress</option>
                    <option value="completed">Completed</option>
                    <option value="cancelled">Cancelled</option>
                  </select>
                  <input style={styles.filterInput} type="text" placeholder="Search customer or service..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                </div>
                {filteredBookings.length === 0 ? (
                  <div style={styles.emptyState}>No bookings found</div>
