                      {booking.status === 'in-progress' && (
                        <button style={styles.completeBtn} onClick={() => updateBookingStatus(booking._id, 'completed')}>✅ Complete</button>
                      )}
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Earnings Tab */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsHeader}>
                  <h2>💰 Earnings Overview</h2>
                  <select style={styles.periodSelect}>
                    <option>This Week</option>
                    <option>This Month</option>
                    <option>This Year</option>
                  </select>
                </div>

                <div style={styles.earningsGrid}>
                  <div style={styles.earningsCard}><h3>Total Revenue</h3><p style={styles.earningsAmount}>${totalRevenue.toLocaleString()}</p></div>
                  <div style={styles.earningsCard}><h3>Platform Fee (15%)</h3><p style={styles.earningsAmount}>${platformCommission.toLocaleString()}</p></div>
                  <div style={styles.earningsCard}><h3>Your Earnings</h3><p style={styles.earningsAmount}>${(totalRevenue - platformCommission).toLocaleString()}</p></div>
                  <div style={styles.earningsCard}><h3>Completed Jobs</h3><p style={styles.earningsAmount}>{completedBookings.length}</p></div>
                </div>

                {/* Daily Breakdown */}
                <div style={styles.card}>
                  <h3>📊 Daily Breakdown</h3>
                  <div style={styles.dailyBreakdown}>
                    {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => (
                      <div key={day} style={styles.dailyItem}>
                        <span>{day}</span>
                        <span>${Math.floor(Math.random() * 500)}</span>
                      </div>
