                      <span>{idx + 1}. {service.name}</span>
                      <span>${service.revenue.toLocaleString()}</span>
                      <div style={styles.revenueBar}>
                        <div style={{ ...styles.revenueFill, width: totalRevenue > 0 ? `${(service.revenue / totalRevenue) * 100}%` : '0%' }}></div>
